// Helper function to extract client ID from composite keys
func extractTestClientID(key string) string {
	if strings.HasPrefix(key, "apikey:") {
		parts := strings.Split(key, "|")
		if len(parts) > 0 {
			return strings.TrimPrefix(parts[0], "apikey:")
		}
	}
	return key
}

