		func(r *http.Request) string { return "test" },
	)

	// Create a test request
	req := httptest.NewRequest("GET", "/?client_id=test123", nil)
	ctx := context.Background()

	// Test with Redis available
	allowed, _, _, err := limiter.AllowRequest(ctx, req)
