	// Verify we can still get the config from memory
	cfg, err = limiter.GetClientConfig(ctx, "test123")
	assert.NoError(t, err)
	assert.Equal(t, 20, cfg.RequestLimit)
	assert.Equal(t, int64(2097152), cfg.ByteLimit)
